create policy "worker can read visible job photos" on public.job_photos for select to authenticated using (private.current_app_role()='operator' and exists(select 1 from public.jobs j where j.id=job_id and j.status<>'tuhistatud'));
create policy "worker can add visible job photos" on public.job_photos for insert to authenticated with check (private.current_app_role()='operator' and uploaded_by=auth.uid() and exists(select 1 from public.jobs j where j.id=job_id and j.status<>'tuhistatud'));
create policy "worker can upload visible job photos" on storage.objects for insert to authenticated with check (bucket_id='job-photos' and private.current_app_role()='operator' and exists(select 1 from public.jobs j where j.id::text=split_part(name,'/',1) and j.status<>'tuhistatud'));
create policy "worker can view visible job photo files" on storage.objects for select to authenticated using (bucket_id='job-photos' and private.current_app_role()='operator' and exists(select 1 from public.job_photos p join public.jobs j on j.id=p.job_id where p.storage_path=name and j.status<>'tuhistatud'));
